-- Final Bronze setup checks; legacy prototype counts are not prerequisites.
SELECT check_name, actual, expected, IFF(actual=expected,'OK','FAIL') AS status FROM (
SELECT 'real_source_tables' AS check_name, COUNT(*) AS actual, 5 AS expected FROM SIDEFLIX.INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA='BRONZE' AND TABLE_NAME IN ('IMDB_RAW','MOVIELENS_RAW','NETFLIX_RAW','WIKIDATA_RAW','WIKIMEDIA_RAW')
UNION ALL SELECT 'raw_metadata_columns', COUNT(*),25 FROM SIDEFLIX.INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA='BRONZE' AND TABLE_NAME IN ('IMDB_RAW','MOVIELENS_RAW','NETFLIX_RAW','WIKIDATA_RAW','WIKIMEDIA_RAW') AND COLUMN_NAME IN ('RAW','_SOURCE_FILE','_LOADED_AT','_BATCH_ID','SOURCE_SYSTEM')
UNION ALL SELECT 'catalog_metadata',COUNT(*),5 FROM SIDEFLIX.INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA='BRONZE' AND TABLE_NAME='CATALOG' AND COLUMN_NAME IN ('IMDB_TCONST','SOURCE_SYSTEM','_SOURCE_FILE','_LOADED_AT','_BATCH_ID')
UNION ALL SELECT 'sessions_metadata',COUNT(*),5 FROM SIDEFLIX.INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA='BRONZE' AND TABLE_NAME='SESSIONS_RAW' AND COLUMN_NAME IN ('RAW','SOURCE_SYSTEM','_SOURCE_FILE','_LOADED_AT','_BATCH_ID')
) ORDER BY check_name;
